#!/bin/bash
# Generated by scripts/export-killercoda.ts. Passes (exit 0) when the named checks of lab-m18-configure-shelf pass.
# Environment overrides, for local tests: SHELF_BIN, KUBECONFIG, SHELF_MARKER_DIR, SHELF_COURSE_DIR, SHELF_LABS_DIR.
LAB=lab-m18-configure-shelf
CHECKS="api-available page-size-from-configmap env-reaches-the-container file-reaches-the-container secret-is-a-volume secret-is-mounted secret-not-in-env configmap-immutable checksum-annotation"
MARK="${SHELF_MARKER_DIR:-/tmp}"
SHELF="${SHELF_BIN:-/usr/local/bin/shelf}"
[ -f "$MARK/shelf-failed" ] && { echo "Setup failed: $(cat "$MARK/shelf-failed"). See /tmp/shelf-setup.log." >&2; exit 1; }
[ -f "$MARK/shelf-ready" ] || { echo "Setup is not finished. Wait for RESULT: ready in the first terminal, then click Check again." >&2; exit 1; }
export KUBECONFIG="${KUBECONFIG:-/root/.kube/config}"
cd "${SHELF_COURSE_DIR:-/root/course}" || { echo "The course folder is missing." >&2; exit 1; }
kubectl --context kind-reconcile --request-timeout=10s get nodes >/dev/null 2>&1 || { echo "The cluster is not reachable. Create it first (shelf up), and wait for the node to be Ready." >&2; exit 1; }
# Only this step's checks run, and each wait is capped at 30 s: the lab's own checks.yaml is replaced in a temporary copy of the labs folder.
LABS="${SHELF_LABS_DIR:-${SHELF_COURSE_DIR:-/root/course}/labs}"
T=$(mktemp -d) || { echo "Cannot make a temporary folder." >&2; exit 1; }
trap '[ -n "$T" ] && rm -rf "$T"' EXIT
for e in "$LABS"/*; do n=${e##*/}; [ "$n" = "$LAB" ] || ln -s "$e" "$T/$n"; done
cp -R "$LABS/$LAB" "$T/$LAB"
cat > "$T/$LAB/checks.yaml" <<'KILLERCODA_CHECKS'
apiVersion: labs.reconcile.example/v1
kind: LabChecks
lab: lab-m18-configure-shelf
checks:
  - id: api-available
    describe: The api is available
    kubectl:
      - get
      - deployment
      - shelf-api
      - -n
      - shelf
      - -o
      - jsonpath={.status.availableReplicas}
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          equals: "1"
    hint: "Apply the file first: `kubectl apply --filename config-lab/shelf-api.yaml`. Then run `kubectl get pods --namespace shelf` and `kubectl describe pod --namespace shelf -l app.kubernetes.io/name=shelf-api`."
  - id: page-size-from-configmap
    describe: SHELF_PAGE_SIZE comes from the ConfigMap key page-size (valueFrom, not a literal)
    kubectl:
      - get
      - deployment
      - shelf-api
      - -n
      - shelf
      - -o
      - jsonpath={.spec.template.spec.containers[?(@.name=='api')].env[?(@.name=='SHELF_PAGE_SIZE')].valueFrom.configMapKeyRef.key}
    expect:
      equals: page-size
    hint: "TODO 2: `env` takes `valueFrom: { configMapKeyRef: { name: shelf-api-config-v1, key: page-size } }` for the name SHELF_PAGE_SIZE."
  - id: env-reaches-the-container
    describe: The running api reports the page size 15 from its environment
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          httpGet:
            url: http://shelf-api.shelf.svc:8081/api/info
            status: 200
            bodyMatches: '"pageSize":15'
    hint: "The api reports its effective settings at /api/info. A page size of 20 is the default: the variable is missing or empty. Run `kubectl get deployment shelf-api --namespace shelf --output jsonpath='{.spec.template.spec.containers[0].env}'`."
  - id: file-reaches-the-container
    describe: The running api reports the banner text from the mounted settings file
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          httpGet:
            url: http://shelf-api.shelf.svc:8081/api/info
            status: 200
            bodyMatches: '"bannerText":"Configured in the lab"'
    hint: "The api reads /etc/shelf/config.yaml. Mount the ConfigMap volume at /etc/shelf: the key config.yaml becomes the file config.yaml. TODO 3."
  - id: secret-is-a-volume
    describe: The Secret shelf-db is a volume of the Pod template
    kubectl:
      - get
      - deployment
      - shelf-api
      - -n
      - shelf
      - -o
      - jsonpath={.spec.template.spec.volumes[*].secret.secretName}
    expect:
      matches: (^| )shelf-db( |$)
    hint: "TODO 4: under `volumes`, `secret: { secretName: shelf-db }`."
  - id: secret-is-mounted
    describe: The api container mounts a volume at /var/run/secrets/shelf
    kubectl:
      - get
      - deployment
      - shelf-api
      - -n
      - shelf
      - -o
      - jsonpath={.spec.template.spec.containers[?(@.name=='api')].volumeMounts[?(@.mountPath=='/var/run/secrets/shelf')].name}
    expect:
      matches: .+
    hint: "A `volumeMounts` entry on the api container with `mountPath: /var/run/secrets/shelf` and the name of the Secret volume."
  - id: secret-not-in-env
    describe: No env var of the Pod template comes from a Secret
    kubectl:
      - get
      - deployment
      - shelf-api
      - -n
      - shelf
      - -o
      - jsonpath={.spec.template.spec.containers[*].env[*].valueFrom.secretKeyRef.name}{.spec.template.spec.containers[*].envFrom[*].secretRef.name}{.spec.template.spec.containers[*].env[?(@.name=='SHELF_DB_PASSWORD')].name}
    expect:
      matches: ^$
    hint: The password belongs in a file. Remove any `secretKeyRef`, `secretRef` or SHELF_DB_PASSWORD from `env` and `envFrom`.
  - id: configmap-immutable
    describe: The ConfigMap shelf-api-config-v1 is immutable
    kubectl:
      - get
      - configmap
      - shelf-api-config-v1
      - -n
      - shelf
      - -o
      - jsonpath={.immutable}
    expect:
      equals: "true"
    hint: "TODO 1: `immutable: true` at the top level of the ConfigMap, next to `data`. Apply the file again: a ConfigMap that is already applied accepts the change from nothing to true."
  - id: checksum-annotation
    describe: The Pod template carries checksum/config with a SHA-256 value
    kubectl:
      - get
      - deployment
      - shelf-api
      - -n
      - shelf
      - -o
      - jsonpath={.spec.template.metadata.annotations['checksum/config']}
    expect:
      matches: ^[0-9a-f]{64}$
    hint: "TODO 5: the annotation goes under `spec.template.metadata`, not the Deployment's own metadata. A SHA-256 hash has 64 hexadecimal characters."
KILLERCODA_CHECKS
out=$(SHELF_LABS_DIR="$T" timeout 60 "$SHELF" verify "$LAB" 2>&1); rc=$?
if [ "$rc" -eq 124 ]; then echo "The checks took too long. Wait a few seconds and click Check again." >&2; exit 1; fi
if [ "$rc" -ge 2 ]; then echo "$out" >&2; exit 1; fi
bad=0
for id in $CHECKS; do
  printf '%s\n' "$out" | grep -Eq "^(PASS|SKIP) $id " && continue
  bad=1; printf '%s\n' "$out" | grep -E -A2 "^FAIL $id "
done
[ "$bad" -eq 0 ] || echo "If you just applied a change, it may still be rolling out: wait a few seconds and click Check again." >&2
exit "$bad"
